INSERT INTO sim_scenario (scenario_code, scenario_name, description, expected_outcome) VALUES
  ('HAPPY', 'Happy Path', 'Validates → screens → creates pacs.008 → routes through correspondent/intermediary → settles → emits pacs.002 ACCC.', 'COMPLETED'),
  ('TIMEOUT', 'Correspondent Timeout', 'The payment reaches the correspondent but receives no acknowledgement. The simulator opens an investigation rather than falsely marking the payment complete.', 'FAILED'),
  ('AC03', 'AC03 Return', 'Beneficiary account validation fails. The original credit transfer is rejected and a return path is created using pacs.004.', 'RETURNED'),
  ('SCREEN', 'Screening Hold', 'Potential screening match creates a hold. Human review is required before release; the simulator then continues with a cleared payment.', 'COMPLETED');
